  "クラウドネイティブ = コンテナ・マイクロサービス・宣言的 API・疎結合で、回復力とスケールを得る考え方": "雲端原生＝透過容器、微服務、宣告式 API、鬆散耦合獲得韌性與擴展性的思維",
  "可観測性の三本柱: メトリクス（Prometheus）・ログ・トレース（OpenTelemetry / Jaeger）": "可觀測性的三大支柱：指標（Prometheus）、日誌、追蹤（OpenTelemetry / Jaeger）",
