  "宣言的な管理と自己サービス（EX280）": "宣告式管理與自助服務（EX280）",
  "マニフェスト・クォータ・テンプレートでプロジェクトを管理できる": "能用資訊清單、配額、範本管理專案",
  "`oc create -f` / `oc apply -f` / `oc get -o yaml` / `oc patch` / `oc set` を使い、手作業を再現可能にする": "使用 `oc create -f` / `oc apply -f` / `oc get -o yaml` / `oc patch` / `oc set`，讓手動作業可以重現",
  "`oc new-project` を一般ユーザーに許可するのは self-provisioner ロール（外すと管理者のみが作成）": "允許一般使用者 `oc new-project` 的是 self-provisioner 角色（拿掉就只有管理員能建立）",
  "Namespace ごとの上限は ResourceQuota と LimitRange。新規 Project の既定は Project テンプレートで設定": "每個 Namespace 的上限用 ResourceQuota 與 LimitRange。新 Project 的預設用 Project 範本設定",
  "アプリの雛形は Template（`oc process -f tpl.yaml -p NAME=app | oc apply -f -`）": "應用程式的雛形用 Template（`oc process -f tpl.yaml -p NAME=app | oc apply -f -`）",
  "Operator は Subscription で導入（1 つの Namespace か全クラスタ）。`oc get csv` で導入済みを確認": "Operator 用 Subscription 導入（單一 Namespace 或整個叢集）。用 `oc get csv` 確認已導入的",
