  "プロジェクト内で使えるメモリ・CPU・Pod 数の合計を制限するリソースは？": "限制專案內可用記憶體、CPU、Pod 數總量的資源是？",
  "コンテナ単位の既定値・上下限は LimitRange。両方を組み合わせるのが定番です。": "容器層級的預設值、上下限是 LimitRange。兩者組合使用是標準做法。",
  "稼働中の Deployment のイメージを宣言的に差し替えるコマンドは？": "以宣告式替換執行中 Deployment 映像檔的指令是？",
  "`oc set env` `oc set resources` も同様に、マニフェストを部分的に更新します。": "`oc set env` `oc set resources` 也同樣會部分更新資訊清單。",
  "Operator が導入されているかを確認するコマンドは？": "確認 Operator 是否已導入的指令是？",
