  "永続ボリュームを与え、アプリをバックアップ・復元できる": "能提供持久磁碟區，並備份、還原應用程式",
  "Kubernetes と同じ PVC / StorageClass。ODF（OpenShift Data Foundation）は内部モードで Ceph ベースのストレージを提供": "與 Kubernetes 相同的 PVC / StorageClass。ODF（OpenShift Data Foundation）以內部模式提供 Ceph 為基礎的儲存",
  "ODF が提供するのは RBD（ブロック・RWO）・CephFS（共有・RWX）・オブジェクト（RGW / NooBaa）": "ODF 提供 RBD（區塊、RWO）、CephFS（共用、RWX）、物件（RGW / NooBaa）",
  "`oc set volume deployment/app --add --claim-name=data --mount-path=/var/lib/data` でボリュームを追加": "用 `oc set volume deployment/app --add --claim-name=data --mount-path=/var/lib/data` 新增磁碟區",
