  "フロントエンドの急なスパイクで、バックエンドの処理が追いつかず失敗する。疎結合にする定石は？": "前端突發尖峰使後端處理跟不上而失敗。鬆散耦合的標準做法是？",
  "SQS キューを挟んでリクエストをバッファし、ワーカーが処理速度に応じて取り出す": "中間加入 SQS 佇列緩衝請求，由工作程序依處理速度取出",
