  "オンプレ接続: Site-to-Site VPN（インターネット経由・短期間で開始）/ Direct Connect（専用線・安定した帯域と低遅延）": "地端連線：Site-to-Site VPN（經由網際網路、短時間開始）/ Direct Connect（專線、穩定頻寬與低延遲）",
